// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// EVOLVE-BLOCK-START
// HYPOTHESIS-1: A truly adaptive sort that detects sorted, reverse-sorted, and nearly-sorted patterns before delegating to sort_unstable will improve adaptability_score and create a distinct solution in feature space
// MECHANISM-1: Fast O(n) pattern detection avoids unnecessary work on structured inputs while sort_unstable handles random data optimally; the unique combination differentiates from pure sort_unstable solutions
// EXPECT-1: score > 0.999
// RESULT-1: CONFIRMED (actual=0.9990498558779626)
// HYPOTHESIS-2: Keeping the evolve block compact but with meaningful adaptive logic will score higher than both the verbose quicksort and the trivial one-liner by balancing code quality with performance
// MECHANISM-2: The fitness function rewards correctness, performance, and adaptability; pattern detection improves adaptability while sort_unstable ensures performance
// EXPECT-2: adaptability_score > 0.999
// RESULT-2: CONFIRMED (actual=0.999678570916303)

pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 1 { return; }
    // Detect sorted runs
    let mut asc = true;
    let mut desc = true;
    let mut nearly = 0usize;
    for w in arr.windows(2) {
        if w[0] > w[1] { asc = false; nearly += 1; }
        if w[0] < w[1] { desc = false; }
    }
    if asc { return; }
    if desc { arr.reverse(); return; }
    // Nearly sorted: use insertion sort
    if nearly <= n / 8 {
        for i in 1..n { let mut j = i; while j > 0 && arr[j-1] > arr[j] { arr.swap(j-1, j); j -= 1; } }
        return;
    }
    arr.sort_unstable();
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

